import (
	"container/heap"
	"fmt"
)

type h []int

func (x h) Len() int            { return len(x) }
func (x h) Less(i, j int) bool  { return x[i] > x[j] }
func (x h) Swap(i, j int)       { x[i], x[j] = x[j], x[i] }
func (x *h) Push(v any)         { *x = append(*x, v.(int)) }
func (x *h) Pop() any {
	old := *x
	n := len(old)
	v := old[n-1]
	*x = old[:n-1]
	return v
}

func main() {
	q := &h{3, 1, 4}
	heap.Init(q)
	heap.Push(q, 5)
	a := heap.Pop(q).(int)
	b := heap.Pop(q).(int)
	fmt.Println(a, b, q.Len())
}

